#[derive(Clone, Debug)]
pub struct CdpConfig {
    pub headful: bool,
    pub initial_url: String,
    pub cdp_url: Option<String>,
    pub snapshot_timeout: Duration,
    pub action_timeout: Duration,
    pub max_elements: usize,
    pub max_text_len: usize,
    pub max_scroll: i64,
    pub max_wait_ms: u64,
}

impl Default for CdpConfig {
    fn default() -> Self {
        Self {
            headful: false,
            initial_url: "about:blank".to_string(),
            cdp_url: None,
            snapshot_timeout: Duration::from_secs(5),
            action_timeout: Duration::from_secs(10),
            max_elements: 50,
            max_text_len: 4000,
            max_scroll: 2000,
            max_wait_ms: 30_000,
        }
    }
}

#[derive(Debug)]
struct Timeouts {
    snapshot: Duration,
    action: Duration,
}

#[derive(Debug)]
struct CdpSession {
    browser: Mutex<ChromiumBrowser>,
    page: Mutex<Page>,
    handler_task: Mutex<Option<tokio::task::JoinHandle<()>>>,
    owns_browser: bool,
    closed: AtomicBool,
}

impl CdpSession {
    async fn launch(config: &CdpConfig) -> BrowserResult<Self> {
        let mut builder = BrowserConfig::builder();
        if config.headful {
            builder = builder.with_head();
        }
        let browser_config = builder
            .build()
            .map_err(|err| BrowserError::new("config_error", err))?;
        let (browser, mut handler) = ChromiumBrowser::launch(browser_config)
            .await
            .map_err(|err| BrowserError::new("cdp_launch_failed", err.to_string()))?;
        let handler_task = tokio::spawn(async move {
            while let Some(_event) = handler.next().await {}
        });
        let page = create_page(&browser, &config.initial_url).await?;

        Ok(Self {
            browser: Mutex::new(browser),
            page: Mutex::new(page),
            handler_task: Mutex::new(Some(handler_task)),
            owns_browser: true,
            closed: AtomicBool::new(false),
        })
    }

    async fn connect(config: &CdpConfig, url: &str) -> BrowserResult<Self> {
        let (browser, mut handler) = ChromiumBrowser::connect(url)
            .await
            .map_err(|err| BrowserError::new("cdp_connect_failed", err.to_string()))?;
        let handler_task = tokio::spawn(async move {
            while let Some(_event) = handler.next().await {}
        });
        let page = create_page(&browser, &config.initial_url).await?;

        Ok(Self {
            browser: Mutex::new(browser),
            page: Mutex::new(page),
            handler_task: Mutex::new(Some(handler_task)),
            owns_browser: false,
            closed: AtomicBool::new(false),
        })
    }

    async fn shutdown(&self) -> BrowserResult<()> {
        if self.closed.swap(true, Ordering::SeqCst) {
            return Ok(());
        }

        let page = self.page.lock().await.clone();
        page.close()
            .await
            .map_err(|err| BrowserError::new("cdp_page_close_failed", err.to_string()))?;

        if self.owns_browser {
            let mut browser = self.browser.lock().await;
            browser
                .close()
                .await
                .map_err(|err| BrowserError::new("cdp_close_failed", err.to_string()))?;
        }

        let mut handler_opt = self.handler_task.lock().await;
        if let Some(mut handle) = handler_opt.take() {
            let shutdown_timer = tokio::time::sleep(Duration::from_secs(5));
            tokio::pin!(shutdown_timer);
            tokio::select! {
                result = &mut handle => {
                    if let Err(err) = result {
                        return Err(BrowserError::new("cdp_handler_failed", err.to_string()));
                    }
                }
                _ = &mut shutdown_timer => {
                    handle.abort();
                    let _ = handle.await;
                }
            }
        }

        Ok(())
    }

    async fn page(&self) -> Page {
        self.page.lock().await.clone()
    }
}

async fn create_page(browser: &ChromiumBrowser, initial_url: &str) -> BrowserResult<Page> {
    let page = browser
        .new_page("about:blank")
        .await
        .map_err(|err| BrowserError::new("cdp_page_failed", err.to_string()))?;
    if !initial_url.is_empty() && initial_url != "about:blank" {
        page.goto(initial_url)
            .await
            .map_err(|err| BrowserError::new("cdp_nav_failed", err.to_string()))?;
    }
    Ok(page)
}

#[derive(Debug)]
pub struct CdpBrowser {
    session: CdpSession,
    observer: Observer,
    applier: ActionApplier,
    timeouts: Timeouts,
    element_map: Mutex<HashMap<String, BackendNodeId>>,
}

impl CdpBrowser {
    pub async fn bootstrap(config: CdpConfig) -> BrowserResult<()> {
        let browser = Self::start(config).await?;
        browser.shutdown().await?;
        Ok(())
    }

    pub async fn launch(config: CdpConfig) -> BrowserResult<Self> {
        let session = CdpSession::launch(&config).await?;
        Ok(Self::from_session(session, &config))
    }

    pub async fn start(config: CdpConfig) -> BrowserResult<Self> {
        if let Some(url) = config.cdp_url.as_deref().filter(|value| !value.is_empty()) {
            let session = CdpSession::connect(&config, url).await?;
            Ok(Self::from_session(session, &config))
        } else {
            Self::launch(config).await
        }
    }

    fn from_session(session: CdpSession, config: &CdpConfig) -> Self {
        let observer = Observer::new(ObserverConfig {
            max_elements: config.max_elements,
            max_text_len: config.max_text_len,
        });
        Self {
            session,
            observer,
            applier: ActionApplier::new(config.max_scroll, config.max_wait_ms),
            timeouts: Timeouts {
                snapshot: config.snapshot_timeout,
                action: config.action_timeout,
            },
            element_map: Mutex::new(HashMap::new()),
        }
    }
}

#[async_trait]
impl Browser for CdpBrowser {
    async fn snapshot(&self) -> BrowserResult<Observation> {
        let snapshot = {
            let page = self.session.page().await;
            let result = timeout(self.timeouts.snapshot, self.observer.snapshot(&page)).await;
            match result {
                Ok(snapshot) => snapshot?,
                Err(err) => {
                    return Err(BrowserError::new(
                        "timeout",
                        format!("snapshot timed out: {err}"),
                    ))
                }
            }
        };

        let mut map = self.element_map.lock().await;
        *map = snapshot.element_map;
        Ok(snapshot.observation)
    }

    async fn apply(&self, action: &Action) -> BrowserResult<StepResult> {
        let page = self.session.page().await;
        let map = { self.element_map.lock().await.clone() };
        let timeout_duration = match action {
            Action::Wait { ms } => {
                let wait = Duration::from_millis(*ms);
                let padded = wait
                    .checked_add(Duration::from_millis(50))
                    .unwrap_or(wait);
                if padded > self.timeouts.action {
                    padded
                } else {
                    self.timeouts.action
                }
            }
            _ => self.timeouts.action,
        };
        let result = timeout(
            timeout_duration,
            self.applier.apply(&page, action, Some(&map)),
        )
        .await;
        let step = match result {
            Ok(Ok(outcome)) => action_result_ok_with(outcome),
            Ok(Err(err)) => action_result_err(err),
            Err(err) => action_result_err(ActionError::new(
                "timeout",
                format!("action timed out: {err}"),
            )),
        };
        Ok(step)

) -> Result<(), ActionError> {
    let backend_id = resolve_backend_node_id(id, element_map)?;
    let (x, y) = backend_node_click_point(page, backend_id).await?;
    page.click(Point::new(x, y)).await?;
    Ok(())
}

async fn type_by_id(
    page: &Page,
    id: &str,
    text: &str,
    submit: bool,
    element_map: Option<&HashMap<String, BackendNodeId>>,
) -> Result<(), ActionError> {
    const TYPE_FN: &str = r#"
        function(text) {
            if (!this) {
                return { ok: false, error: "missing_element" };
            }
            try {
                if ("value" in this) {
                    this.value = text;
                } else if (this.isContentEditable) {
                    this.textContent = text;
                } else {
                    return { ok: false, error: "not_editable" };
                }
            } catch (err) {
                return { ok: false, error: "set_value_failed" };
            }
            this.dispatchEvent(new Event("input", { bubbles: true }));
            this.dispatchEvent(new Event("change", { bubbles: true }));
            return { ok: true, value: String(this.value ?? this.textContent ?? "") };
        }
    "#;
    const SUBMIT_FN: &str = r#"
        function() {
            if (!this) {
                return { ok: false, error: "missing_element" };
            }
            let form = this.form;
            if (!form && this.closest) {
                try {
                    form = this.closest("form");
                } catch (err) {
                    form = null;
                }
            }
            if (!form) {
                return { ok: false, error: "missing_form" };
            }
            try {
                if (typeof form.requestSubmit === "function") {
                    form.requestSubmit();
                } else if (typeof form.submit === "function") {
                    form.submit();
                } else {
                    return { ok: false, error: "submit_unavailable" };
                }
            } catch (err) {
                return { ok: false, error: "submit_failed" };
            }
            return { ok: true, value: "submitted" };
        }
    "#;

    let backend_id = resolve_backend_node_id(id, element_map)?;
    focus_backend_node(page, backend_id).await?;
    let value = call_function_on_node(
        page,
        backend_id,
        TYPE_FN,
        vec![Value::String(text.to_string())],
    )
    .await?;
    parse_js_action_result(value, "type_failed")?;
    if submit {
        let submit_result = call_function_on_node(page, backend_id, SUBMIT_FN, Vec::new()).await?;
        let parsed = parse_js_action_result_raw(submit_result)?;
        if parsed.ok {
            return Ok(());
        }
        let error = parsed.error.unwrap_or_else(|| "submit_failed".to_string());
        if error == "missing_form" || error == "submit_unavailable" {
            focus_backend_node(page, backend_id).await?;
            press_key(page, "Enter").await?;
        } else {
            return Err(ActionError::new("submit_failed", error));
        }
    }
    Ok(())
}

#[derive(Debug, Deserialize)]
struct JsActionResult {
    ok: bool,
    #[serde(default)]
    value: Option<String>,
    #[serde(default)]
    error: Option<String>,
}

fn parse_js_action_result_raw(value: Value) -> Result<JsActionResult, ActionError> {
    serde_json::from_value(value)
        .map_err(|err| ActionError::new("js_error", format!("invalid js result: {err}")))
}

fn parse_js_action_result(
    value: Value,
    failure_code: &'static str,
) -> Result<Option<String>, ActionError> {
    let parsed = parse_js_action_result_raw(value)?;
    if parsed.ok {
        Ok(parsed.value)
    } else {
        Err(ActionError::new(
            failure_code,
            parsed
                .error
                .unwrap_or_else(|| "js action failed".to_string()),
        ))
    }
}

async fn call_function_on_node(
    page: &Page,
    backend_node_id: BackendNodeId,
    function_declaration: &str,
    arguments: Vec<Value>,
) -> Result<Value, ActionError> {
    let resolved = page
        .execute(
            ResolveNodeParams::builder()
                .backend_node_id(backend_node_id)
                .build(),
        )
        .await
        .map_err(|err| map_cdp_error(err, "resolve_node"))?;
    let object_id = resolved
        .result
        .object
        .object_id
        .ok_or_else(|| ActionError::new("missing_object_id", "resolve node returned no object"))?;

    let mut builder = CallFunctionOnParams::builder()
        .function_declaration(function_declaration)
        .object_id(object_id)
        .return_by_value(true);
    for argument in arguments {
        builder = builder.argument(CallArgument::builder().value(argument).build());
    }
    let params = builder
        .build()
        .map_err(|err| ActionError::new("js_error", err))?;
    let response = page
        .execute(params)
        .await
        .map_err(|err| map_cdp_error(err, "call_function"))?;
    let call_result = response.result;
    if let Some(details) = call_result.exception_details {
        return Err(ActionError::new(
            "js_error",
            format!("js exception: {details:?}"),
        ));
    }
    let remote: RemoteObject = call_result.result;
    remote
        .value
        .ok_or_else(|| ActionError::new("js_error", "missing js return value"))
}

async fn select_by_id(
    page: &Page,
    id: &str,
    value: &str,
    element_map: Option<&HashMap<String, BackendNodeId>>,
) -> Result<(), ActionError> {
    const SELECT_FN: &str = r#"
        function(value) {
            if (!this) {
                return { ok: false, error: "missing_element" };
            }
            const tag = this.tagName ? this.tagName.toLowerCase() : "";
            if (tag !== "select" && !("value" in this)) {
                return { ok: false, error: "not_select" };
            }
            const needle = String(value);
            let nextValue = needle;
            if (tag === "select" && this.options) {
                const options = Array.from(this.options);
                const match = options.find(
                    (opt) =>
                        opt.value === needle ||
                        opt.label === needle ||
                        opt.text === needle
                );
                if (!match) {
                    return { ok: false, error: "invalid_option" };
                }
                nextValue = match.value;
            }
            try {
                this.value = nextValue;
            } catch (err) {
                return { ok: false, error: "set_value_failed" };
            }
            this.dispatchEvent(new Event("input", { bubbles: true }));
            this.dispatchEvent(new Event("change", { bubbles: true }));
            const actual = String(this.value ?? "");
            if (actual !== nextValue) {
                return { ok: false, error: "selection_mismatch", value: actual };
            }
            return { ok: true, value: actual };
        }
    "#;
    let backend_id = resolve_backend_node_id(id, element_map)?;
    let value = call_function_on_node(
        page,
        backend_id,
        SELECT_FN,
        vec![Value::String(value.to_string())],
    )
    .await?;
    parse_js_action_result(value, "select_failed")?;
    Ok(())
}

async fn extract_by_id(
    page: &Page,
    id: &str,
    query: &str,
    element_map: Option<&HashMap<String, BackendNodeId>>,
) -> Result<String, ActionError> {
    let backend_id = resolve_backend_node_id(id, element_map)?;
    let value = call_function_on_node(
        page,
        backend_id,
        extract_function(),
        vec![Value::String(query.to_string())],
    )
    .await?;
    Ok(parse_js_action_result(value, "extract_failed")?.unwrap_or_default())
}

async fn extract_from_page(page: &Page, query: &str) -> Result<String, ActionError> {
    let query_literal =
        serde_json::to_string(query).map_err(|err| ActionError::new("js_error", err.to_string()))?;
    let script = format!("({})({})", extract_function(), query_literal);
    let result = page.evaluate(script).await?;
    let value = result
        .into_value()
        .map_err(|err| ActionError::new("js_error", format!("extract: {err}")))?;
    Ok(parse_js_action_result(value, "extract_failed")?.unwrap_or_default())
}

fn extract_function() -> &'static str {
    r#"
        function(query) {
            const root = (this && this.querySelectorAll) ? this : document;
            if (!query) {
                return { ok: false, error: "missing_query" };
            }
            let target = null;
            if (query === "self" && root !== document) {
                target = root;
            }
            if (!target) {
                try {
                    if (root.querySelector) {
                        target = root.querySelector(query);
                    }
                } catch (err) {
                    target = null;
                }
            }
            if (!target) {
                try {
                    const needle = String(query).toLowerCase();
                    const nodes = root.querySelectorAll ? root.querySelectorAll("*") : [];
                    for (let i = 0; i < nodes.length && i < 2000; i += 1) {
                        const text = (nodes[i].innerText || nodes[i].textContent || "").trim();
                        if (text && text.toLowerCase().includes(needle)) {
                            target = nodes[i];
                            break;
                        }
                    }
                } catch (err) {
                    target = null;
                }
            }
            if (!target) {
                return { ok: false, error: "not_found" };
            }
            let value = "";
            if ("value" in target) {
                try {
                    value = String(target.value ?? "");
                } catch (err) {
                    value = "";
                }
            }
            if (!value) {
                value = (target.innerText || target.textContent || "").trim();
            }
            return { ok: true, value };
        }
    "#
}

async fn focus_backend_node(page: &Page, backend_node_id: BackendNodeId) -> Result<(), ActionError> {
    let params = FocusParams::builder()
        .backend_node_id(backend_node_id)
        .build();
    page.execute(params)
        .await
        .map_err(|err| map_cdp_error(err, "focus"))?;
    Ok(())
}

async fn backend_node_click_point(
    page: &Page,
    backend_node_id: BackendNodeId,
) -> Result<(f64, f64), ActionError> {
    let model = page
        .execute(
            GetBoxModelParams::builder()
                .backend_node_id(backend_node_id)
                .build(),
        )
        .await
        .map_err(|err| map_cdp_error(err, "get_box_model"))?
        .result
        .model;
    quad_center(model.border.inner())
        .ok_or_else(|| ActionError::new("invalid_box_model", "invalid element box model"))
}

fn quad_center(quad: &[f64]) -> Option<(f64, f64)> {
    if quad.len() != 8 {
        return None;
    }
    let xs = [quad[0], quad[2], quad[4], quad[6]];
    let ys = [quad[1], quad[3], quad[5], quad[7]];
    let (min_x, max_x) = xs.iter().fold((xs[0], xs[0]), |acc, x| {
        (acc.0.min(*x), acc.1.max(*x))
    });
    let (min_y, max_y) = ys.iter().fold((ys[0], ys[0]), |acc, y| {
        (acc.0.min(*y), acc.1.max(*y))
    });
    Some(((min_x + max_x) / 2.0, (min_y + max_y) / 2.0))
}

fn parse_backend_node_id(id: &str) -> Result<BackendNodeId, ActionError> {
    let raw = id
        .strip_prefix("el_")
        .ok_or_else(|| ActionError::new("invalid_element_id", "missing el_ prefix"))?;
    let parsed = raw
        .parse::<i64>()
        .map_err(|_| ActionError::new("invalid_element_id", "invalid backend node id"))?;
    Ok(BackendNodeId::new(parsed))
}

fn resolve_backend_node_id(
    id: &str,
    element_map: Option<&HashMap<String, BackendNodeId>>,
) -> Result<BackendNodeId, ActionError> {
    if let Some(map) = element_map {
        return map.get(id).cloned().ok_or_else(|| {
            ActionError::new(
                "stale_element",
                format!("id {id} not found in latest observation"),
            )
        });
    }
    parse_backend_node_id(id)
}

async fn press_key(page: &Page, key: &str) -> Result<(), ActionError> {
    let key_definition = keys::get_key_definition(key)
        .ok_or_else(|| ActionError::new("invalid_key", format!("key not found: {key}")))?;
    let mut cmd = DispatchKeyEventParams::builder();
    let key_down_event_type = if let Some(txt) = key_definition.text {
        cmd = cmd.text(txt);
        DispatchKeyEventType::KeyDown
    } else if key_definition.key.len() == 1 {
        cmd = cmd.text(key_definition.key);
        DispatchKeyEventType::KeyDown
    } else {
        DispatchKeyEventType::RawKeyDown
    };

    cmd = cmd
        .r#type(DispatchKeyEventType::KeyDown)
        .key(key_definition.key)
        .code(key_definition.code)
        .windows_virtual_key_code(key_definition.key_code)
        .native_virtual_key_code(key_definition.key_code);

    page.execute(cmd.clone().r#type(key_down_event_type).build().unwrap())
        .await?;
    page.execute(cmd.r#type(DispatchKeyEventType::KeyUp).build().unwrap())
        .await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;
    use serde_json::json;

    #[test]
    fn parse_backend_node_id_accepts_el_prefix() {
        let id = parse_backend_node_id("el_42").expect("parse id");
        assert_eq!(*id.inner(), 42);
    }

    #[test]
    fn parse_backend_node_id_rejects_invalid() {
        assert!(parse_backend_node_id("42").is_err());
        assert!(parse_backend_node_id("el_nope").is_err());
    }

    #[test]
    fn quad_center_returns_midpoint() {
        let quad = vec![0.0, 0.0, 10.0, 0.0, 10.0, 20.0, 0.0, 20.0];
        let center = quad_center(&quad).unwrap();
        assert_eq!(center.0, 5.0);
        assert_eq!(center.1, 10.0);
    }

    #[test]
    fn resolve_backend_node_id_prefers_map() {
        let mut map = HashMap::new();
        map.insert("el_deadbeef_1".to_string(), BackendNodeId::new(7));
        let resolved =
            resolve_backend_node_id("el_deadbeef_1", Some(&map)).expect("resolve id");
        assert_eq!(*resolved.inner(), 7);
    }

    #[test]
    fn resolve_backend_node_id_requires_latest_map_entry() {
        let map: HashMap<String, BackendNodeId> = HashMap::new();
        let err = resolve_backend_node_id("el_missing_1", Some(&map)).unwrap_err();
        assert_eq!(err.code, "stale_element");
    }

    #[test]
    fn resolve_backend_node_id_falls_back_to_parse() {
        let map = HashMap::new();
        let resolved = resolve_backend_node_id("el_42", Some(&map)).expect("resolve id");
        assert_eq!(*resolved.inner(), 42);
    }

    #[test]
    fn parse_js_action_result_accepts_ok() {
        let value = json!({"ok": true, "value": "done"});
        let parsed = parse_js_action_result(value, "select_failed").expect("parse result");
        assert_eq!(parsed, Some("done".to_string()));
    }

    #[test]
    fn parse_js_action_result_reports_failure() {
        let value = json!({"ok": false, "error": "not_found"});
        let err = parse_js_action_result(value, "extract_failed").expect_err("expect error");
        assert_eq!(err.code, "extract_failed");
        assert_eq!(err.message, "not_found");
    }

    #[test]
    fn parse_js_action_result_rejects_invalid() {
        let value = json!(true);
        let err = parse_js_action_result(value, "extract_failed").expect_err("expect error");
        assert_eq!(err.code, "js_error");
    }
}
